    /*   Applies symmetric Gauss-Seidel preconditioner to symmetric system A * x = b, */
    /*   that is, it solves:                                                          */
    /*      x0       = alpha*x                                                        */
    /*      (L+D)*x1 = b - U*x0                                                       */
    /*      (D+U)*x  = b - L*x1                                                       */
    /*                                                                                */
    /*   SYMGS_MV also returns y = A*x                                                */
    public static native @Cast("sparse_status_t") int mkl_sparse_s_symgs( @Cast("const sparse_operation_t") int op,
                                             sparse_matrix A,
                                             @Const @ByVal matrix_descr descr,
                                             float alpha,
                                             @Const FloatPointer b,
                                             FloatPointer x);
