    /*   Computes an action of a preconditioner
         which corresponds to the approximate matrix decomposition A ~ (L+D)*E*(U+D)
         for the system Ax = b.

         L is lower triangular part of A
         U is upper triangular part of A
         D is diagonal values of A
         E is approximate diagonal inverse

         That is, it solves:
             r = rhs - A*x0
             (L + D)*E*(U + D)*dx = r
             x1 = x0 + dx                                        */

    public static native @Cast("sparse_status_t") int mkl_sparse_s_lu_smoother( @Cast("const sparse_operation_t") int op,
                                                   sparse_matrix A,
                                                   @Const @ByVal matrix_descr descr,
                                                   @Const FloatPointer diag,
                                                   @Const FloatPointer approx_diag_inverse,
                                                   FloatPointer x,
                                                   @Const FloatPointer rhs);
    public static native @Cast("sparse_status_t") int mkl_sparse_s_lu_smoother( @Cast("const sparse_operation_t") int op,
                                                   sparse_matrix A,
                                                   @Const @ByVal matrix_descr descr,
                                                   @Const FloatBuffer diag,
                                                   @Const FloatBuffer approx_diag_inverse,
                                                   FloatBuffer x,
                                                   @Const FloatBuffer rhs);
